def _g_z_gate(fd, F):
    if fd.action != "buy" or F["z"] is None:
        return None
    gates = {"accumulation": -0.5, "consolidation": -1.0, "distribution": -1.5, "markup": 0, "unknown": -1.0}
    thr = gates.get(F["cycle_phase"], -1.0)
    if F["z"] > thr:
        return ("🟡 Z偏高·等待更优入场",
                f"Z={F['z']} 要求≤{thr}，估值未达极端低位",
                "item_z_gate")
    return None

